//! Localhost HTTP admin API — the bot side of the shared Discord admin router
//! (`ircbot_core/discord_admin.py`). Implements the same contract used by the other bots:
//!
//! * `GET  /health`            -> `{"ok":true}` (no auth)
//! * `POST /v1/command`        -> `{"messages":[...]}`  (Bearer auth; body `{"command","args"}`)
//! * `GET  /v1/events?since=N` -> `{"events":[{"id","message"}]}` (Bearer auth)
//!
//! Runs on a dedicated thread (like the DB / module-host threads) and reaches the async runtime via
//! the shared [`ServerRegistry`] (for `say`/`join`/`part`) and a [`Control`] channel
//! (`reload`/`shutdown`). Enabled only when a token is configured; binds localhost by default.

use crate::action::{Control, IrcAction};
use crate::db::DbHandle;
use crate::log_bus::LogBus;
use crate::modules::{ModuleAdminHandle, ServerRegistry};
use jeeves_abi::ModuleAdminCommandRequest;
use std::sync::{Arc, Mutex};
use tiny_http::{Header, Method, Request, Response, Server};
use tokio::sync::mpsc;

/// Ring buffer of events surfaced to Discord via `/v1/events`.
#[derive(Default)]
pub struct EventLog {
    items: Vec<(i64, String)>,
    next_id: i64,
}

impl EventLog {
    pub fn push(&mut self, message: String) {
        self.next_id += 1;
        self.items.push((self.next_id, message));
        let overflow = self.items.len().saturating_sub(500);
        if overflow > 0 {
            self.items.drain(0..overflow);
        }
    }

    fn since(&self, since: i64) -> Vec<(i64, String)> {
        self.items
            .iter()
            .filter(|(id, _)| *id > since)
            .cloned()
            .collect()
    }
}

/// Shared state the admin API needs to act on the running bot.
#[derive(Clone)]
pub struct AdminState {
    pub db: DbHandle,
    pub registry: ServerRegistry,
    pub control: mpsc::Sender<Control>,
    pub modules: Arc<Mutex<Vec<String>>>,
    pub module_admin: Option<ModuleAdminHandle>,
    pub events: Arc<Mutex<EventLog>>,
}

/// Start the admin API server on its own thread. No-op-with-error-log if the bind fails.
pub fn serve(bind: String, token: String, state: AdminState, log: LogBus) {
    std::thread::Builder::new()
        .name("jeeves-adminapi".into())
        .spawn(move || {
            let server = match Server::http(&bind) {
                Ok(s) => s,
                Err(e) => {
                    log.error("adminapi", format!("failed to bind {bind}: {e}"));
                    return;
                }
            };
            log.info("adminapi", format!("admin API listening on http://{bind}"));
            for request in server.incoming_requests() {
                handle(request, &token, &state, &log);
            }
        })
        .ok();
}

fn handle(mut req: Request, token: &str, state: &AdminState, log: &LogBus) {
    let (path, query) = split_url(req.url());

    // Health is unauthenticated.
    if req.method() == &Method::Get && path == "/health" {
        let _ = req.respond(json_response(200, r#"{"ok":true}"#));
        return;
    }

    if !authorized(&req, token) {
        let _ = req.respond(json_response(401, r#"{"error":"unauthorized"}"#));
        return;
    }

    match (req.method(), path.as_str()) {
        (&Method::Get, "/v1/events") => {
            let since = query_param(&query, "since")
                .and_then(|s| s.parse::<i64>().ok())
                .unwrap_or(0);
            let events = state.events.lock().unwrap().since(since);
            let body = serde_json::json!({
                "events": events.iter().map(|(id, m)| serde_json::json!({"id": id, "message": m})).collect::<Vec<_>>()
            });
            let _ = req.respond(json_response(200, &body.to_string()));
        }
        (&Method::Post, "/v1/command") => {
            let mut body = String::new();
            if req.as_reader().read_to_string(&mut body).is_err() {
                let _ = req.respond(json_response(400, r#"{"error":"unreadable body"}"#));
                return;
            }
            let parsed: serde_json::Value = match serde_json::from_str(&body) {
                Ok(v) => v,
                Err(_) => {
                    let _ = req.respond(json_response(400, r#"{"error":"invalid json"}"#));
                    return;
                }
            };
            let command = parsed
                .get("command")
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .trim()
                .to_string();
            let args = parsed
                .get("args")
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .trim()
                .to_string();
            if command.is_empty() {
                let _ = req.respond(json_response(400, r#"{"error":"command is required"}"#));
                return;
            }
            log.log(
                jeeves_abi::Level::Info,
                jeeves_abi::Category::Command,
                "adminapi",
                format!("discord: {command} {args}"),
            );
            let messages = dispatch(state, &command, &args);
            let body = serde_json::json!({ "messages": messages });
            let _ = req.respond(json_response(200, &body.to_string()));
        }
        _ => {
            let _ = req.respond(json_response(404, r#"{"error":"not found"}"#));
        }
    }
}

/// Route a command to bot actions and return human-readable result lines. Pure except for the
/// channel sends it triggers — unit-tested via a fake [`AdminState`].
pub fn dispatch(state: &AdminState, command: &str, args: &str) -> Vec<String> {
    match command.to_lowercase().as_str() {
        "help" => vec![
            "commands: status, modules, reload, refresh, shutdown, ignore, unignore, wordle,"
                .into(),
            "say <server> <target> <message>, join <server> <#chan>, part <server> <#chan>".into(),
            "ignore <server> <nick>, unignore <server> <nick>".into(),
            "wordle <server> <nick> new | wordle <server> <nick> chances <1-10>".into(),
            "(<server> may be omitted when only one network is connected)".into(),
        ],
        "status" => {
            let nets = network_list(state);
            let mods = state.modules.lock().unwrap();
            vec![
                format!("networks ({}): {}", nets.len(), join_or_none(&nets)),
                format!("modules ({}): {}", mods.len(), join_or_none(&mods)),
            ]
        }
        "modules" => {
            let mods = state.modules.lock().unwrap();
            vec![format!("modules ({}): {}", mods.len(), join_or_none(&mods))]
        }
        "reload" => {
            let _ = state.control.try_send(Control::Reload);
            vec!["reloading modules…".into()]
        }
        "refresh" => {
            let _ = state.control.try_send(Control::Refresh);
            vec!["reconnecting all networks…".into()]
        }
        "shutdown" | "kill" => {
            let _ = state.control.try_send(Control::Shutdown);
            vec!["shutting down. goodbye.".into()]
        }
        "ignore" => cmd_ignore(state, args, true),
        "unignore" => cmd_ignore(state, args, false),
        "say" => cmd_say(state, args),
        "join" => cmd_chan(state, args, true),
        "part" => cmd_chan(state, args, false),
        "wordle" => cmd_wordle(state, args),
        other => vec![format!("unknown command '{other}'. try 'help'.")],
    }
}

fn cmd_ignore(state: &AdminState, args: &str, ignored: bool) -> Vec<String> {
    let networks = network_list(state);
    let Some((server, rest)) = resolve_server(&networks, args) else {
        return vec![format!(
            "specify a network. connected: {}",
            join_or_none(&networks)
        )];
    };
    let nick = rest.trim();
    if nick.is_empty() || nick.split_whitespace().count() != 1 {
        return vec![format!(
            "usage: {} <server> <nick>",
            if ignored { "ignore" } else { "unignore" }
        )];
    }
    match state
        .db
        .profile_set_ignored_by_nick_blocking(&server, nick, ignored)
    {
        Ok(Some(true)) => {
            let verb = if ignored {
                "ignoring"
            } else {
                "no longer ignoring"
            };
            vec![format!("{verb} {nick} on {server}.")]
        }
        Ok(Some(false)) => {
            let state = if ignored {
                "already ignored"
            } else {
                "was not ignored"
            };
            vec![format!("{nick} on {server} {state}.")]
        }
        Ok(None) => vec![format!(
            "no known profile for {nick} on {server}; they must speak to the bot first"
        )],
        Err(error) => vec![format!(
            "{} command failed: {error}",
            if ignored { "ignore" } else { "unignore" }
        )],
    }
}

fn cmd_wordle(state: &AdminState, args: &str) -> Vec<String> {
    let networks = network_list(state);
    let Some((server, args)) = resolve_server(&networks, args) else {
        return vec![format!(
            "specify a network. connected: {}",
            join_or_none(&networks)
        )];
    };
    if args.split_whitespace().count() < 2 {
        return vec![
            "usage: wordle <server> <nick> new | wordle <server> <nick> chances <1-10>".into(),
        ];
    }
    let Some(module_admin) = &state.module_admin else {
        return vec!["module admin bridge is unavailable".into()];
    };
    match module_admin.command_blocking("wordle", ModuleAdminCommandRequest { server, args }) {
        Ok(response) => response.messages,
        Err(error) => vec![format!("wordle admin command failed: {error}")],
    }
}

fn cmd_say(state: &AdminState, args: &str) -> Vec<String> {
    let nets = network_list(state);
    let Some((server, rest)) = resolve_server(&nets, args) else {
        return vec![format!(
            "specify a network. connected: {}",
            join_or_none(&nets)
        )];
    };
    let mut it = rest.trim().splitn(2, char::is_whitespace);
    let target = it.next().unwrap_or("").trim();
    let message = it.next().unwrap_or("").trim();
    if target.is_empty() || message.is_empty() {
        return vec!["usage: say <server> <target> <message>".into()];
    }
    match send_action(
        state,
        &server,
        IrcAction::Privmsg {
            target: target.into(),
            text: message.into(),
        },
    ) {
        Ok(()) => vec![format!("sent to {target} on {server}.")],
        Err(e) => vec![e],
    }
}

fn cmd_chan(state: &AdminState, args: &str, join: bool) -> Vec<String> {
    let nets = network_list(state);
    let Some((server, rest)) = resolve_server(&nets, args) else {
        return vec![format!(
            "specify a network. connected: {}",
            join_or_none(&nets)
        )];
    };
    let channel = rest.trim();
    if channel.is_empty() {
        return vec![format!(
            "usage: {} <server> <#channel>",
            if join { "join" } else { "part" }
        )];
    }
    let action = if join {
        IrcAction::Join(channel.into())
    } else {
        IrcAction::Part(channel.into())
    };
    let verb = if join { "joining" } else { "parting" };
    match send_action(state, &server, action) {
        Ok(()) => vec![format!("{verb} {channel} on {server}.")],
        Err(e) => vec![e],
    }
}

/// Split the leading `<server>` token from `args` when it names a connected network; otherwise, if
/// exactly one network is connected, use it and treat all of `args` as the remainder.
fn resolve_server(networks: &[String], args: &str) -> Option<(String, String)> {
    let mut it = args.trim().splitn(2, char::is_whitespace);
    let first = it.next().unwrap_or("");
    let rest = it.next().unwrap_or("");
    if networks.iter().any(|n| n == first) {
        Some((first.to_string(), rest.to_string()))
    } else if networks.len() == 1 {
        Some((networks[0].clone(), args.trim().to_string()))
    } else {
        None
    }
}

fn send_action(state: &AdminState, server: &str, action: IrcAction) -> Result<(), String> {
    let reg = state.registry.lock().unwrap();
    match reg.get(server) {
        Some(tx) => tx
            .try_send(action)
            .map_err(|_| format!("send queue full for '{server}'")),
        None => Err(format!("not connected to '{server}'")),
    }
}

fn network_list(state: &AdminState) -> Vec<String> {
    let mut nets: Vec<String> = state.registry.lock().unwrap().keys().cloned().collect();
    nets.sort();
    nets
}

fn join_or_none(items: &[String]) -> String {
    if items.is_empty() {
        "(none)".into()
    } else {
        items.join(", ")
    }
}

// ---- HTTP helpers ----

fn authorized(req: &Request, token: &str) -> bool {
    let expected = format!("Bearer {token}");
    for h in req.headers() {
        if h.field
            .as_str()
            .as_str()
            .eq_ignore_ascii_case("authorization")
        {
            return constant_time_eq(h.value.as_str().as_bytes(), expected.as_bytes());
        }
    }
    false
}

fn constant_time_eq(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() {
        return false;
    }
    let mut diff = 0u8;
    for (x, y) in a.iter().zip(b.iter()) {
        diff |= x ^ y;
    }
    diff == 0
}

fn split_url(url: &str) -> (String, String) {
    match url.split_once('?') {
        Some((p, q)) => (p.to_string(), q.to_string()),
        None => (url.to_string(), String::new()),
    }
}

fn query_param(query: &str, key: &str) -> Option<String> {
    query.split('&').find_map(|pair| {
        let (k, v) = pair.split_once('=')?;
        (k == key).then(|| v.to_string())
    })
}

fn json_response(status: u16, body: &str) -> Response<std::io::Cursor<Vec<u8>>> {
    let header = Header::from_bytes(&b"Content-Type"[..], &b"application/json"[..]).unwrap();
    Response::from_string(body)
        .with_status_code(status)
        .with_header(header)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashMap;

    fn state_with(
        networks: &[&str],
    ) -> (
        AdminState,
        HashMap<String, mpsc::Receiver<IrcAction>>,
        mpsc::Receiver<Control>,
    ) {
        let mut registry = HashMap::new();
        let mut receivers = HashMap::new();
        for n in networks {
            let (tx, rx) = mpsc::channel(8);
            registry.insert(n.to_string(), tx);
            receivers.insert(n.to_string(), rx);
        }
        let (ctl_tx, ctl_rx) = mpsc::channel(8);
        let state = AdminState {
            db: DbHandle::open(":memory:").unwrap(),
            registry: Arc::new(Mutex::new(registry)),
            control: ctl_tx,
            modules: Arc::new(Mutex::new(vec!["admin".into(), "users".into()])),
            module_admin: None,
            events: Arc::new(Mutex::new(EventLog::default())),
        };
        (state, receivers, ctl_rx)
    }

    #[test]
    fn say_enqueues_privmsg_on_named_server() {
        let (state, mut rx, _ctl) = state_with(&["libera", "ergo"]);
        let out = dispatch(&state, "say", "ergo #chan hello there");
        assert!(out[0].contains("sent to #chan on ergo"), "{out:?}");
        match rx.get_mut("ergo").unwrap().try_recv().unwrap() {
            IrcAction::Privmsg { target, text } => {
                assert_eq!(target, "#chan");
                assert_eq!(text, "hello there");
            }
            other => panic!("expected privmsg, got {other:?}"),
        }
    }

    #[test]
    fn say_omits_server_when_single_network() {
        let (state, mut rx, _ctl) = state_with(&["only"]);
        let out = dispatch(&state, "say", "#room hi");
        assert!(out[0].contains("on only"), "{out:?}");
        assert!(matches!(
            rx.get_mut("only").unwrap().try_recv().unwrap(),
            IrcAction::Privmsg { .. }
        ));
    }

    #[test]
    fn say_requires_server_when_multiple() {
        let (state, _rx, _ctl) = state_with(&["a", "b"]);
        let out = dispatch(&state, "say", "#room hi");
        assert!(out[0].contains("specify a network"), "{out:?}");
    }

    #[test]
    fn wordle_requires_network_when_multiple_and_valid_arguments() {
        let (state, _rx, _ctl) = state_with(&["a", "b"]);
        let out = dispatch(&state, "wordle", "notziggy new");
        assert!(out[0].contains("specify a network"), "{out:?}");

        let (state, _rx, _ctl) = state_with(&["a"]);
        let out = dispatch(&state, "wordle", "notziggy");
        assert!(out[0].contains("usage:"), "{out:?}");
    }

    #[test]
    fn ignore_and_unignore_use_the_stable_profile() {
        let (state, _rx, _ctl) = state_with(&["libera"]);
        state
            .db
            .profile_ensure_blocking("libera", "Alice", 100)
            .unwrap();
        let profile = state
            .db
            .profile_get_blocking("libera", "Alice")
            .unwrap()
            .unwrap();

        assert!(dispatch(&state, "ignore", "libera Alice")[0].contains("ignoring Alice"));
        assert!(state
            .db
            .profile_is_ignored_blocking("libera", &profile.id)
            .unwrap());
        assert!(
            dispatch(&state, "unignore", "libera Alice")[0].contains("no longer ignoring Alice")
        );
        assert!(!state
            .db
            .profile_is_ignored_blocking("libera", &profile.id)
            .unwrap());
    }

    #[test]
    fn control_commands_signal() {
        let (state, _rx, mut ctl) = state_with(&["x"]);
        dispatch(&state, "reload", "");
        assert!(matches!(ctl.try_recv().unwrap(), Control::Reload));
        dispatch(&state, "shutdown", "");
        assert!(matches!(ctl.try_recv().unwrap(), Control::Shutdown));
    }

    #[test]
    fn status_lists_networks_and_modules() {
        let (state, _rx, _ctl) = state_with(&["libera"]);
        let out = dispatch(&state, "status", "");
        assert!(out.iter().any(|l| l.contains("libera")));
        assert!(out.iter().any(|l| l.contains("admin")));
    }

    #[test]
    fn unknown_command_is_friendly() {
        let (state, _rx, _ctl) = state_with(&["x"]);
        assert!(dispatch(&state, "frobnicate", "")[0].contains("unknown command"));
    }

    #[test]
    fn event_log_since() {
        let mut log = EventLog::default();
        log.push("a".into());
        log.push("b".into());
        let after_first = log.since(1);
        assert_eq!(after_first.len(), 1);
        assert_eq!(after_first[0].1, "b");
    }
}

//! Read-only public achievement gallery and JSON API.

use crate::db::{DbHandle, PublicAchievementHolder};
use crate::log_bus::LogBus;
use crate::modules::AchievementRegistry;
use jeeves_abi::{AchievementManifest, AchievementProfileSummary};
use serde::Serialize;
use sha2::{Digest, Sha256};
use std::collections::HashMap;
use std::net::IpAddr;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
use tiny_http::{Header, Method, Request, Response, Server, StatusCode};

const MAX_RESPONSE_BYTES: usize = 512 * 1024;
const RATE_LIMIT_PER_MINUTE: u32 = 120;
const REQUEST_TIMEOUT: Duration = Duration::from_secs(5);
type RouteResponse = (u16, &'static str, String, u32);

#[derive(Clone)]
pub struct PublicWebState {
    pub db: DbHandle,
    pub achievements: AchievementRegistry,
}

#[derive(Default)]
struct RateLimiter {
    clients: HashMap<IpAddr, (Instant, u32)>,
}

#[derive(Serialize)]
struct CatalogResponse {
    version: u32,
    modules: Vec<PublicModule>,
    totals: PublicTotals,
}

#[derive(Serialize)]
struct PublicModule {
    module: String,
    achievements: Vec<PublicAchievement>,
    prestige: Vec<PublicPrestige>,
}

#[derive(Serialize)]
struct PublicAchievement {
    id: String,
    name: String,
    description: Option<String>,
    optional: bool,
    secret: bool,
    earned: Option<bool>,
    current: Option<u64>,
    threshold: Option<u64>,
}

#[derive(Serialize)]
struct PublicPrestige {
    id: String,
    name: String,
    first_threshold: u64,
    every: u64,
    rank: Option<u64>,
}

#[derive(Default, Serialize)]
struct PublicTotals {
    achievements: usize,
    modules: usize,
    prestige_tracks: usize,
    earned: Option<usize>,
}

#[derive(Serialize)]
struct UsersResponse {
    version: u32,
    users: Vec<PublicUser>,
}

#[derive(Clone, Serialize)]
struct PublicUser {
    server: String,
    profile: String,
    nick: String,
    label: String,
}

#[derive(Serialize)]
struct CollectionResponse {
    version: u32,
    user: PublicUser,
    modules: Vec<PublicModule>,
    totals: PublicTotals,
}

pub fn serve(bind: String, state: PublicWebState, log: LogBus) {
    std::thread::Builder::new()
        .name("jeeves-public-web".into())
        .spawn(move || {
            let server = match Server::http(&bind) {
                Ok(server) => server,
                Err(error) => {
                    log.error("publicweb", format!("failed to bind {bind}: {error}"));
                    return;
                }
            };
            log.info(
                "publicweb",
                format!("public gallery listening on http://{bind}"),
            );
            let limiter = Arc::new(Mutex::new(RateLimiter::default()));
            for request in server.incoming_requests() {
                handle(request, &state, &limiter, &log);
            }
        })
        .ok();
}

fn handle(request: Request, state: &PublicWebState, limiter: &Mutex<RateLimiter>, log: &LogBus) {
    let (path, query) = split_url(request.url());
    if path != "/health" && !rate_allowed(&request, limiter) {
        respond_text(
            request,
            429,
            "text/plain; charset=utf-8",
            "rate limit exceeded",
            0,
        );
        return;
    }
    if request.method() != &Method::Get && request.method() != &Method::Head {
        respond_text(
            request,
            405,
            "text/plain; charset=utf-8",
            "method not allowed",
            0,
        );
        return;
    }
    let head = request.method() == &Method::Head;
    let (tx, rx) = std::sync::mpsc::sync_channel(1);
    let route_state = state.clone();
    std::thread::spawn(move || {
        let _ = tx.send(route(&route_state, &path, &query));
    });
    match rx.recv_timeout(REQUEST_TIMEOUT) {
        Ok(Ok((status, content_type, body, max_age))) => {
            respond_cached(request, status, content_type, body, max_age, head)
        }
        Ok(Err(error)) => {
            log.error("publicweb", format!("request failed: {error}"));
            respond_text(
                request,
                500,
                "application/json",
                r#"{"error":"internal error"}"#,
                0,
            );
        }
        Err(_) => respond_text(
            request,
            503,
            "application/json",
            r#"{"error":"request timeout"}"#,
            0,
        ),
    }
}

fn route(state: &PublicWebState, path: &str, query: &str) -> anyhow::Result<RouteResponse> {
    match path {
        "/health" => Ok((200, "application/json", r#"{"ok":true}"#.into(), 0)),
        "/ready" => {
            let ready = !state.achievements.lock().unwrap().is_empty();
            Ok((
                if ready { 200 } else { 503 },
                "application/json",
                format!(r#"{{"ready":{ready}}}"#),
                0,
            ))
        }
        "/style.css" => Ok((200, "text/css; charset=utf-8", STYLE.into(), 3600)),
        "/v1/catalog" => catalog(state).and_then(|value| json_body(&value, 60)),
        "/v1/users" => users(state).and_then(|value| json_body(&value, 15)),
        "/v1/collection" => {
            let server = query_param(query, "server");
            let profile = query_param(query, "profile");
            match (server, profile) {
                (Some(server), Some(profile)) => collection(state, &server, &profile),
                _ => Ok((
                    400,
                    "application/json",
                    r#"{"error":"missing server or profile"}"#.into(),
                    0,
                )),
            }
        }
        "/" => page(state, query).map(|body| (200, "text/html; charset=utf-8", body, 15)),
        _ => Ok((404, "text/plain; charset=utf-8", "not found".into(), 0)),
    }
}

fn manifests(state: &PublicWebState) -> Vec<(String, AchievementManifest)> {
    let mut values = state
        .achievements
        .lock()
        .unwrap()
        .iter()
        .map(|(name, manifest)| (name.clone(), manifest.clone()))
        .collect::<Vec<_>>();
    values.sort_by(|a, b| a.0.cmp(&b.0));
    values
}

fn catalog(state: &PublicWebState) -> anyhow::Result<CatalogResponse> {
    let modules = manifests(state)
        .into_iter()
        .map(|(module, manifest)| public_module(&module, &manifest, None))
        .collect::<Vec<_>>();
    Ok(CatalogResponse {
        version: 1,
        totals: totals(&modules, None),
        modules,
    })
}

fn eligible_users(state: &PublicWebState) -> anyhow::Result<Vec<PublicUser>> {
    let catalogs = manifests(state);
    let mut users = Vec::new();
    for holder in state.db.public_achievement_holders_blocking()? {
        if owns_current_finite(&holder, &catalogs) {
            users.push(public_user(holder));
        }
    }
    Ok(users)
}

fn owns_current_finite(
    holder: &PublicAchievementHolder,
    catalogs: &[(String, AchievementManifest)],
) -> bool {
    holder.unlocks.iter().any(|(module, achievement_id)| {
        catalogs.iter().any(|(catalog_module, manifest)| {
            catalog_module == module
                && manifest
                    .achievements
                    .iter()
                    .any(|spec| &spec.id == achievement_id)
        })
    })
}

fn public_user(holder: PublicAchievementHolder) -> PublicUser {
    PublicUser {
        label: format!("{} — {}", holder.nick, holder.server),
        server: holder.server,
        profile: holder.profile_id,
        nick: holder.nick,
    }
}

fn users(state: &PublicWebState) -> anyhow::Result<UsersResponse> {
    Ok(UsersResponse {
        version: 1,
        users: eligible_users(state)?,
    })
}

fn collection(
    state: &PublicWebState,
    server: &str,
    profile: &str,
) -> anyhow::Result<(u16, &'static str, String, u32)> {
    if server.len() > 100 || profile.len() > 100 {
        return Ok((
            404,
            "application/json",
            r#"{"error":"not found"}"#.into(),
            0,
        ));
    }
    let Some(user) = eligible_users(state)?
        .into_iter()
        .find(|user| user.server == server && user.profile == profile)
    else {
        return Ok((
            404,
            "application/json",
            r#"{"error":"not found"}"#.into(),
            0,
        ));
    };
    let catalogs = manifests(state);
    let summary = state
        .db
        .achievements_get_blocking(server, profile, catalogs.clone())?;
    let modules = catalogs
        .iter()
        .map(|(module, manifest)| public_module(module, manifest, Some(&summary)))
        .collect::<Vec<_>>();
    let response = CollectionResponse {
        version: 1,
        totals: totals(&modules, Some(&summary)),
        modules,
        user,
    };
    json_body(&response, 15)
}

fn public_module(
    module: &str,
    manifest: &AchievementManifest,
    summary: Option<&AchievementProfileSummary>,
) -> PublicModule {
    let progress = summary.and_then(|summary| summary.modules.iter().find(|m| m.module == module));
    let mut achievements = manifest
        .achievements
        .iter()
        .filter_map(|spec| {
            let status = progress
                .and_then(|module| module.achievements.iter().find(|item| item.id == spec.id));
            let earned = status.is_some_and(|item| item.earned);
            if spec.secret && !earned {
                return None;
            }
            Some(PublicAchievement {
                id: spec.id.clone(),
                name: spec.name.clone(),
                description: (!spec.secret).then(|| spec.description.clone()),
                optional: spec.optional,
                secret: spec.secret,
                earned: summary.map(|_| earned),
                current: (!spec.secret).then(|| status.map_or(0, |item| item.current)),
                threshold: (!spec.secret).then_some(spec.threshold),
            })
        })
        .collect::<Vec<_>>();
    achievements.sort_by(|a, b| a.name.cmp(&b.name));
    let prestige = manifest
        .prestige
        .iter()
        .map(|spec| PublicPrestige {
            id: spec.id.clone(),
            name: spec.name.clone(),
            first_threshold: spec.first_threshold,
            every: spec.every,
            rank: progress.and_then(|module| {
                module
                    .prestige
                    .iter()
                    .find(|rank| rank.id == spec.id)
                    .map(|rank| rank.rank)
            }),
        })
        .collect();
    PublicModule {
        module: module.into(),
        achievements,
        prestige,
    }
}

fn totals(modules: &[PublicModule], summary: Option<&AchievementProfileSummary>) -> PublicTotals {
    PublicTotals {
        achievements: modules.iter().map(|module| module.achievements.len()).sum(),
        modules: modules.len(),
        prestige_tracks: modules.iter().map(|module| module.prestige.len()).sum(),
        earned: summary.map(|_| {
            modules
                .iter()
                .flat_map(|module| &module.achievements)
                .filter(|item| item.earned == Some(true))
                .count()
        }),
    }
}

fn page(state: &PublicWebState, query: &str) -> anyhow::Result<String> {
    let users = eligible_users(state)?;
    let selected = query_param(query, "holder")
        .and_then(|holder| {
            holder
                .split_once('|')
                .map(|(server, profile)| (server.to_string(), profile.to_string()))
        })
        .and_then(|(server, profile)| {
            users
                .iter()
                .find(|user| user.server == server && user.profile == profile)
                .cloned()
        });
    let catalogs = manifests(state);
    let summary = selected
        .as_ref()
        .map(|user| {
            state
                .db
                .achievements_get_blocking(&user.server, &user.profile, catalogs.clone())
        })
        .transpose()?;
    let modules = catalogs
        .iter()
        .map(|(module, manifest)| public_module(module, manifest, summary.as_ref()))
        .collect::<Vec<_>>();
    let totals = totals(&modules, summary.as_ref());
    let mut html = String::from("<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Jeeves Achievement Gallery</title><link rel=\"stylesheet\" href=\"/style.css\"></head><body><header><p class=\"eyebrow\">JEEVES</p><h1>Achievement Gallery</h1><p>Collections earned across the IRC fleet.</p></header><main>");
    html.push_str("<form method=\"get\" action=\"/\"><label for=\"holder\">Achievement holder</label><select id=\"holder\" name=\"holder\"><option value=\"\">Catalog overview</option>");
    for user in &users {
        let is_selected = selected.as_ref().is_some_and(|current| {
            current.profile == user.profile && current.server == user.server
        });
        let selected_attr = if is_selected { " selected" } else { "" };
        html.push_str(&format!(
            "<option value=\"{}|{}\"{}>{}</option>",
            escape(&user.server),
            escape(&user.profile),
            selected_attr,
            escape(&user.label)
        ));
    }
    html.push_str("</select><button type=\"submit\">View collection</button></form>");
    if users.is_empty() {
        html.push_str(
            "<p class=\"notice\">No achievement holders have published a collection yet.</p>",
        );
    }
    html.push_str(&format!("<section class=\"summary\"><strong>{}</strong> achievements · <strong>{}</strong> modules · <strong>{}</strong> prestige tracks", totals.achievements, totals.modules, totals.prestige_tracks));
    if let Some(earned) = totals.earned {
        html.push_str(&format!(" · <strong>{earned}</strong> earned"));
    }
    html.push_str("</section><nav aria-label=\"Modules\">");
    for module in &modules {
        html.push_str(&format!(
            "<a href=\"#module-{}\">{}</a>",
            escape(&module.module),
            escape(&module.module)
        ));
    }
    html.push_str("</nav>");
    for module in &modules {
        html.push_str(&format!(
            "<section class=\"module\" id=\"module-{}\"><h2>{}</h2><div class=\"grid\">",
            escape(&module.module),
            escape(&module.module)
        ));
        for item in &module.achievements {
            let class = match (item.earned, item.secret, item.optional) {
                (Some(true), true, _) => "card earned secret",
                (Some(true), _, true) => "card earned optional",
                (Some(true), _, _) => "card earned",
                (Some(false), _, true) => "card locked optional",
                (Some(false), _, _) => "card locked",
                (None, _, true) => "card optional",
                _ => "card",
            };
            html.push_str(&format!(
                "<article class=\"{class}\"><h3>{}</h3>",
                escape(&item.name)
            ));
            if item.secret {
                html.push_str("<span class=\"tag\">Earned secret</span>");
            }
            if item.optional {
                html.push_str("<span class=\"tag\">Optional</span>");
            }
            if let Some(description) = &item.description {
                html.push_str(&format!("<p>{}</p>", escape(description)));
            }
            if let (Some(current), Some(threshold)) = (item.current, item.threshold) {
                html.push_str(&format!("<progress value=\"{current}\" max=\"{threshold}\"></progress><small>{current} / {threshold}</small>"));
            }
            html.push_str("</article>");
        }
        for prestige in &module.prestige {
            html.push_str(&format!("<article class=\"card prestige\"><h3>{}</h3><span class=\"tag\">Prestige</span><p>Begins at {} and advances every {}.</p>", escape(&prestige.name), prestige.first_threshold, prestige.every));
            if let Some(rank) = prestige.rank.filter(|rank| *rank > 0) {
                html.push_str(&format!("<strong>Rank {rank}</strong>"));
            }
            html.push_str("</article>");
        }
        html.push_str("</div></section>");
    }
    html.push_str("</main><footer>Read-only gallery · Profiles appear only by explicit opt-in.</footer></body></html>");
    Ok(html)
}

fn rate_allowed(request: &Request, limiter: &Mutex<RateLimiter>) -> bool {
    let Some(peer) = request.remote_addr().map(|address| address.ip()) else {
        return true;
    };
    // Trust Cloudflare's client address only from the loopback reverse proxy/tunnel.
    let ip = if peer.is_loopback() {
        request
            .headers()
            .iter()
            .find(|header| header.field.equiv("CF-Connecting-IP"))
            .and_then(|header| header.value.as_str().parse().ok())
            .unwrap_or(peer)
    } else {
        peer
    };
    let now = Instant::now();
    let mut limiter = limiter.lock().unwrap();
    limiter
        .clients
        .retain(|_, (start, _)| now.duration_since(*start) < Duration::from_secs(120));
    let entry = limiter.clients.entry(ip).or_insert((now, 0));
    if now.duration_since(entry.0) >= Duration::from_secs(60) {
        *entry = (now, 0);
    }
    entry.1 += 1;
    entry.1 <= RATE_LIMIT_PER_MINUTE
}

fn json_body<T: Serialize>(
    value: &T,
    max_age: u32,
) -> anyhow::Result<(u16, &'static str, String, u32)> {
    let body = serde_json::to_string(value)?;
    if body.len() > MAX_RESPONSE_BYTES {
        anyhow::bail!("public response exceeds size limit");
    }
    Ok((200, "application/json", body, max_age))
}

fn respond_cached(
    request: Request,
    status: u16,
    content_type: &str,
    body: String,
    max_age: u32,
    head: bool,
) {
    if body.len() > MAX_RESPONSE_BYTES {
        respond_text(
            request,
            500,
            "text/plain; charset=utf-8",
            "response too large",
            0,
        );
        return;
    }
    let etag = format!("\"{:x}\"", Sha256::digest(body.as_bytes()));
    let not_modified = request.headers().iter().any(|header| {
        header.field.equiv("If-None-Match") && header.value.as_str() == etag.as_str()
    });
    let actual_status = if not_modified { 304 } else { status };
    let actual_body = if not_modified || head {
        String::new()
    } else {
        body
    };
    let mut response =
        Response::from_string(actual_body).with_status_code(StatusCode(actual_status));
    for (name, value) in security_headers(content_type, max_age) {
        if let Ok(header) = Header::from_bytes(name, value) {
            response.add_header(header);
        }
    }
    if let Ok(header) = Header::from_bytes("ETag", etag) {
        response.add_header(header);
    }
    let _ = request.respond(response);
}

fn respond_text(request: Request, status: u16, content_type: &str, body: &str, max_age: u32) {
    respond_cached(request, status, content_type, body.into(), max_age, false)
}

fn security_headers(content_type: &str, max_age: u32) -> Vec<(&'static str, String)> {
    vec![
        ("Content-Type", content_type.into()),
        ("Cache-Control", format!("public, max-age={max_age}")),
        ("Content-Security-Policy", "default-src 'none'; style-src 'self'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'".into()),
        ("X-Content-Type-Options", "nosniff".into()),
        ("Referrer-Policy", "no-referrer".into()),
        ("X-Frame-Options", "DENY".into()),
        ("Permissions-Policy", "camera=(), microphone=(), geolocation=()".into()),
    ]
}

fn split_url(url: &str) -> (String, String) {
    let (path, query) = url.split_once('?').unwrap_or((url, ""));
    (path.to_string(), query.to_string())
}

fn query_param(query: &str, key: &str) -> Option<String> {
    query.split('&').find_map(|pair| {
        let (name, value) = pair.split_once('=').unwrap_or((pair, ""));
        (name == key).then(|| percent_decode(value))
    })
}

fn percent_decode(value: &str) -> String {
    let bytes = value.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut index = 0;
    while index < bytes.len() {
        match bytes[index] {
            b'+' => {
                out.push(b' ');
                index += 1;
            }
            b'%' if index + 2 < bytes.len() => {
                let decoded = std::str::from_utf8(&bytes[index + 1..index + 3])
                    .ok()
                    .and_then(|hex| u8::from_str_radix(hex, 16).ok());
                if let Some(decoded) = decoded {
                    out.push(decoded);
                    index += 3;
                } else {
                    out.push(bytes[index]);
                    index += 1;
                }
            }
            byte => {
                out.push(byte);
                index += 1;
            }
        }
    }
    String::from_utf8_lossy(&out).into_owned()
}

fn escape(value: &str) -> String {
    let mut out = String::with_capacity(value.len());
    for ch in value.chars() {
        match ch {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#39;"),
            _ => out.push(ch),
        }
    }
    out
}

