    #[tokio::test]
    async fn quit_action_writes_quit_before_connection_closes() {
        use crate::casemapping::CaseMappingRegistry;
        use crate::config::ServerConfig;
        use tokio::io::AsyncReadExt;

        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let port = listener.local_addr().unwrap().port();

        let cfg = ServerConfig {
            id: 0,
            label: "test".into(),
            enabled: true,
            host: "127.0.0.1".into(),
            port,
            tls: false,
            nick: "jeeves".into(),
            username: "jeeves".into(),
            realname: "rustjeeves".into(),
            sasl_account: None,
            sasl_password: None,
            nick_password: None,
            channels: Vec::new(),
            accept_invalid_certs: false,
            umodes: None,
        };

        let (action_tx, mut action_rx) = tokio::sync::mpsc::channel::<IrcAction>(8);
        let (event_tx, _event_rx) = tokio::sync::mpsc::channel::<super::EventEnvelope>(16);
        let log = dummy_log();
        let casemappings = CaseMappingRegistry::default();

        let actor = tokio::spawn(async move {
            super::run(cfg, log, &mut action_rx, event_tx, casemappings).await
        });

        // Accept the loopback connection so the actor is connected and entering its select loop
        // when the quit is requested below.
        let (mut sock, _addr) = listener.accept().await.unwrap();

        action_tx
            .send(IrcAction::Quit(Some("orderly departure".into())))
            .await
            .unwrap();

        // Read every wire byte the actor writes until it closes the connection. The QUIT frame
        // must reach the peer before EOF; the previous sleep-based flush never polled the
        // ClientStream, so the peer observed a bare disconnect.
        let mut buf = Vec::new();
        let read = tokio::time::timeout(
            std::time::Duration::from_secs(1),
            sock.read_to_end(&mut buf),
        )
        .await;
        assert!(
            read.is_ok(),
            "peer read timed out waiting for connection close"
        );
        let text = String::from_utf8(buf).expect("wire bytes must be UTF-8");
        assert!(
            text.contains("QUIT :orderly departure\r\n"),
            "missing QUIT frame in wire bytes: {text:?}"
        );

        let exit = actor.await.unwrap().unwrap();
        assert_eq!(exit, super::RunExit::StopRequested);
    }
}

//! Localhost HTTP admin API — the bot side of the shared Discord admin router
//! (`ircbot_core/discord_admin.py`). Implements the same contract used by the other bots:
//!
//! * `GET  /health`            -> `{"ok":true}` (no auth)
//! * `POST /v1/command`        -> `{"messages":[...]}`  (Bearer auth; body `{"command","args"}`)
//! * `GET  /v1/events?since=N` -> `{"events":[{"id","message"}]}` (Bearer auth)
//!
//! Runs on a dedicated thread (like the DB / module-host threads) and reaches the async runtime via
//! the shared [`ServerRegistry`] (for `say`/`join`/`part`) and a [`Control`] channel
//! (`reload`/`shutdown`). Enabled only when a token is configured; binds localhost by default.

use crate::action::{Control, IrcAction};
use crate::db::DbHandle;
use crate::log_bus::LogBus;
use crate::modules::{ModuleAdminHandle, ServerRegistry};
use jeeves_abi::ModuleAdminCommandRequest;
use std::sync::{Arc, Mutex};
use tiny_http::{Header, Method, Request, Response, Server};
use tokio::sync::mpsc;

/// Ring buffer of events surfaced to Discord via `/v1/events`.
#[derive(Default)]
pub struct EventLog {
    items: Vec<(i64, String)>,
    next_id: i64,
}

impl EventLog {
    pub fn push(&mut self, message: String) {
        self.next_id += 1;
        self.items.push((self.next_id, message));
        let overflow = self.items.len().saturating_sub(500);
        if overflow > 0 {
            self.items.drain(0..overflow);
        }
    }

    fn since(&self, since: i64) -> Vec<(i64, String)> {
        self.items
            .iter()
            .filter(|(id, _)| *id > since)
            .cloned()
            .collect()
    }
}

/// Shared state the admin API needs to act on the running bot.
#[derive(Clone)]
pub struct AdminState {
    pub db: DbHandle,
    pub registry: ServerRegistry,
    pub control: mpsc::Sender<Control>,
    pub modules: Arc<Mutex<Vec<String>>>,
    pub module_admin: Option<ModuleAdminHandle>,
    pub events: Arc<Mutex<EventLog>>,
}

/// Start the admin API server on its own thread. No-op-with-error-log if the bind fails.
pub fn serve(bind: String, token: String, state: AdminState, log: LogBus) {
    std::thread::Builder::new()
        .name("jeeves-adminapi".into())
        .spawn(move || {
            let server = match Server::http(&bind) {
                Ok(s) => s,
                Err(e) => {
                    log.error("adminapi", format!("failed to bind {bind}: {e}"));
                    return;
                }
            };
            log.info("adminapi", format!("admin API listening on http://{bind}"));
            for request in server.incoming_requests() {
                handle(request, &token, &state, &log);
            }
        })
        .ok();
}

fn handle(mut req: Request, token: &str, state: &AdminState, log: &LogBus) {
    let (path, query) = split_url(req.url());

    // Health is unauthenticated.
    if req.method() == &Method::Get && path == "/health" {
        let _ = req.respond(json_response(200, r#"{"ok":true}"#));
        return;
    }

    if !authorized(&req, token) {
        let _ = req.respond(json_response(401, r#"{"error":"unauthorized"}"#));
        return;
    }

    match (req.method(), path.as_str()) {
        (&Method::Get, "/v1/events") => {
            let since = query_param(&query, "since")
                .and_then(|s| s.parse::<i64>().ok())
                .unwrap_or(0);
            let events = state.events.lock().unwrap().since(since);
            let body = serde_json::json!({
                "events": events.iter().map(|(id, m)| serde_json::json!({"id": id, "message": m})).collect::<Vec<_>>()
            });
            let _ = req.respond(json_response(200, &body.to_string()));
        }
        (&Method::Post, "/v1/command") => {
            let mut body = String::new();
            if req.as_reader().read_to_string(&mut body).is_err() {
                let _ = req.respond(json_response(400, r#"{"error":"unreadable body"}"#));
                return;
            }
            let parsed: serde_json::Value = match serde_json::from_str(&body) {
                Ok(v) => v,
                Err(_) => {
                    let _ = req.respond(json_response(400, r#"{"error":"invalid json"}"#));
                    return;
                }
            };
            let command = parsed
                .get("command")
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .trim()
                .to_string();
            let args = parsed
                .get("args")
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .trim()
                .to_string();
            if command.is_empty() {
                let _ = req.respond(json_response(400, r#"{"error":"command is required"}"#));
                return;
            }
            log.log(
                jeeves_abi::Level::Info,
                jeeves_abi::Category::Command,
                "adminapi",
                format!("discord: {command} {args}"),
            );
            let messages = dispatch(state, &command, &args);
            let body = serde_json::json!({ "messages": messages });
            let _ = req.respond(json_response(200, &body.to_string()));
        }
        _ => {
            let _ = req.respond(json_response(404, r#"{"error":"not found"}"#));
        }
    }
}

/// Route a command to bot actions and return human-readable result lines. Pure except for the
/// channel sends it triggers — unit-tested via a fake [`AdminState`].
pub fn dispatch(state: &AdminState, command: &str, args: &str) -> Vec<String> {
    match command.to_lowercase().as_str() {
        "help" => vec![
            "commands: status, modules, reload, refresh, shutdown, ignore, unignore, wordle,"
                .into(),
            "say <server> <target> <message>, join <server> <#chan>, part <server> <#chan>".into(),
            "ignore <server> <nick>, unignore <server> <nick>".into(),
            "wordle <server> <nick> new | wordle <server> <nick> chances <1-10>".into(),
            "(<server> may be omitted when only one network is connected)".into(),
        ],
        "status" => {
            let nets = network_list(state);
            let mods = state.modules.lock().unwrap();
            vec![
                format!("networks ({}): {}", nets.len(), join_or_none(&nets)),
                format!("modules ({}): {}", mods.len(), join_or_none(&mods)),
            ]
        }
        "modules" => {
            let mods = state.modules.lock().unwrap();
            vec![format!("modules ({}): {}", mods.len(), join_or_none(&mods))]
        }
        "reload" => {
            let _ = state.control.try_send(Control::Reload);
            vec!["reloading modules…".into()]
        }
        "refresh" => {
            let _ = state.control.try_send(Control::Refresh);
            vec!["reconnecting all networks…".into()]
        }
        "shutdown" | "kill" => {
            let _ = state.control.try_send(Control::Shutdown);
            vec!["shutting down. goodbye.".into()]
        }
        "ignore" => cmd_ignore(state, args, true),
        "unignore" => cmd_ignore(state, args, false),
        "say" => cmd_say(state, args),
        "join" => cmd_chan(state, args, true),
        "part" => cmd_chan(state, args, false),
        "wordle" => cmd_wordle(state, args),
        other => vec![format!("unknown command '{other}'. try 'help'.")],
    }
}

fn cmd_ignore(state: &AdminState, args: &str, ignored: bool) -> Vec<String> {
    let networks = network_list(state);
    let Some((server, rest)) = resolve_server(&networks, args) else {
        return vec![format!(
            "specify a network. connected: {}",
            join_or_none(&networks)
        )];
    };
    let nick = rest.trim();
    if nick.is_empty() || nick.split_whitespace().count() != 1 {
        return vec![format!(
            "usage: {} <server> <nick>",
            if ignored { "ignore" } else { "unignore" }
        )];
    }
    match state
        .db
        .profile_set_ignored_by_nick_blocking(&server, nick, ignored)
    {
        Ok(Some(true)) => {
            let verb = if ignored {
                "ignoring"
            } else {
                "no longer ignoring"
            };
            vec![format!("{verb} {nick} on {server}.")]
        }
        Ok(Some(false)) => {
            let state = if ignored {
                "already ignored"
            } else {
                "was not ignored"
            };
            vec![format!("{nick} on {server} {state}.")]
        }
        Ok(None) => vec![format!(
            "no known profile for {nick} on {server}; they must speak to the bot first"
        )],
        Err(error) => vec![format!(
            "{} command failed: {error}",
            if ignored { "ignore" } else { "unignore" }
        )],
    }
}

fn cmd_wordle(state: &AdminState, args: &str) -> Vec<String> {
    let networks = network_list(state);
    let Some((server, args)) = resolve_server(&networks, args) else {
        return vec![format!(
            "specify a network. connected: {}",
            join_or_none(&networks)
        )];
    };
    if args.split_whitespace().count() < 2 {
        return vec![
            "usage: wordle <server> <nick> new | wordle <server> <nick> chances <1-10>".into(),
        ];
    }
    let Some(module_admin) = &state.module_admin else {
        return vec!["module admin bridge is unavailable".into()];
    };
    match module_admin.command_blocking("wordle", ModuleAdminCommandRequest { server, args }) {
        Ok(response) => response.messages,
        Err(error) => vec![format!("wordle admin command failed: {error}")],
    }
}

fn cmd_say(state: &AdminState, args: &str) -> Vec<String> {
    let nets = network_list(state);
    let Some((server, rest)) = resolve_server(&nets, args) else {
        return vec![format!(
            "specify a network. connected: {}",
            join_or_none(&nets)
        )];
    };
    let mut it = rest.trim().splitn(2, char::is_whitespace);
    let target = it.next().unwrap_or("").trim();
    let message = it.next().unwrap_or("").trim();
    if target.is_empty() || message.is_empty() {
        return vec!["usage: say <server> <target> <message>".into()];
    }
    match send_action(
        state,
        &server,
        IrcAction::Privmsg {
            target: target.into(),
            text: message.into(),
        },
    ) {
        Ok(()) => vec![format!("sent to {target} on {server}.")],
        Err(e) => vec![e],
    }
}

fn cmd_chan(state: &AdminState, args: &str, join: bool) -> Vec<String> {
    let nets = network_list(state);
    let Some((server, rest)) = resolve_server(&nets, args) else {
        return vec![format!(
            "specify a network. connected: {}",
            join_or_none(&nets)
        )];
    };
    let channel = rest.trim();
    if channel.is_empty() {
        return vec![format!(
            "usage: {} <server> <#channel>",
            if join { "join" } else { "part" }
        )];
    }
    let action = if join {
        IrcAction::Join(channel.into())
    } else {
        IrcAction::Part(channel.into())
    };
    let verb = if join { "joining" } else { "parting" };
    match send_action(state, &server, action) {
        Ok(()) => vec![format!("{verb} {channel} on {server}.")],
        Err(e) => vec![e],
    }
}

/// Split the leading `<server>` token from `args` when it names a connected network; otherwise, if
/// exactly one network is connected, use it and treat all of `args` as the remainder.
fn resolve_server(networks: &[String], args: &str) -> Option<(String, String)> {
    let mut it = args.trim().splitn(2, char::is_whitespace);
    let first = it.next().unwrap_or("");
    let rest = it.next().unwrap_or("");
    if networks.iter().any(|n| n == first) {
        Some((first.to_string(), rest.to_string()))
    } else if networks.len() == 1 {
        Some((networks[0].clone(), args.trim().to_string()))
    } else {
        None
    }
}

fn send_action(state: &AdminState, server: &str, action: IrcAction) -> Result<(), String> {
    let reg = state.registry.lock().unwrap();
    match reg.get(server) {
        Some(tx) => tx
            .try_send(action)
            .map_err(|_| format!("send queue full for '{server}'")),
        None => Err(format!("not connected to '{server}'")),
    }
}

fn network_list(state: &AdminState) -> Vec<String> {
    let mut nets: Vec<String> = state.registry.lock().unwrap().keys().cloned().collect();
    nets.sort();
    nets
}

fn join_or_none(items: &[String]) -> String {
    if items.is_empty() {
        "(none)".into()
    } else {
        items.join(", ")
    }
}

// ---- HTTP helpers ----

fn authorized(req: &Request, token: &str) -> bool {
    let expected = format!("Bearer {token}");
    for h in req.headers() {
        if h.field
            .as_str()
            .as_str()
            .eq_ignore_ascii_case("authorization")
        {
            return constant_time_eq(h.value.as_str().as_bytes(), expected.as_bytes());
        }
    }
    false
}

fn constant_time_eq(a: &[u8], b: &[u8]) -> bool {
    if a.len() != b.len() {
        return false;
    }
    let mut diff = 0u8;
    for (x, y) in a.iter().zip(b.iter()) {
        diff |= x ^ y;
    }
    diff == 0
}

fn split_url(url: &str) -> (String, String) {
    match url.split_once('?') {
        Some((p, q)) => (p.to_string(), q.to_string()),
        None => (url.to_string(), String::new()),
    }
}

fn query_param(query: &str, key: &str) -> Option<String> {
    query.split('&').find_map(|pair| {
        let (k, v) = pair.split_once('=')?;
        (k == key).then(|| v.to_string())
    })
}

fn json_response(status: u16, body: &str) -> Response<std::io::Cursor<Vec<u8>>> {
    let header = Header::from_bytes(&b"Content-Type"[..], &b"application/json"[..]).unwrap();
    Response::from_string(body)
        .with_status_code(status)
        .with_header(header)
}

