    account_id: String,
    authorization_token: String,
    api_info: ApiInfo,
}
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct ApiInfo {
    storage_api: StorageApi,
}
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct StorageApi {
    api_url: String,
    allowed: Allowed,
}
#[derive(Deserialize)]
struct Allowed {
